-- CarbonLoop Massive 55+ Organization Enterprise Database Seed SQL Script
-- Compatible with Neon PostgreSQL and standard PostgreSQL 14+
-- Contains 55 Orgs, 55 Facilities, 50 Listings, 40 Requirements, Matches, Orders, Shipments, Invoices & Tracking Events

BEGIN;

-- 0. CLEAN SLATE TRUNCATE
TRUNCATE TABLE 
  system_alerts,
  audit_logs,
  notifications,
  payments,
  invoices,
  shipment_tracking_events,
  shipment_routes,
  shipments,
  logistics_quotes,
  contracts,
  order_items,
  orders,
  offer_items,
  offers,
  inquiries,
  matches,
  match_scores,
  buyer_requirement_status_history,
  buyer_requirements,
  co2_listing_documents,
  co2_listing_status_history,
  co2_listings,
  facility_certifications,
  documents,
  facilities,
  organization_members,
  organizations,
  user_roles,
  users,
  co2_utilization_types,
  roles
CASCADE;

-- 1. ROLES
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description;

-- 2. USERS (Hashed password for "Password123!")
ON CONFLICT (email) DO UPDATE SET first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name;

-- USER ROLES MAPPING
ON CONFLICT DO NOTHING;

-- 3. CO2 UTILIZATION TYPES
ON CONFLICT (code) DO NOTHING;

-- 4. ORGANIZATIONS (55 Enterprise Industrial Organizations)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

-- 5. FACILITIES (55 Industrial Facilities)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;

-- 6. ORGANIZATION MEMBERS
ON CONFLICT (organization_id, user_id) DO NOTHING;

-- 7. DOCUMENTS & FACILITY CERTIFICATIONS
ON CONFLICT (id) DO NOTHING;

ON CONFLICT DO NOTHING;

-- 8. CO2 SUPPLY LISTINGS (50 Active Emitter Listings)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, price_per_unit = EXCLUDED.price_per_unit;

-- 9. BUYER REQUIREMENTS (40 Active Demand Requirements)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, maximum_price_per_unit = EXCLUDED.maximum_price_per_unit;

-- 10. MATCHES & COMPATIBILITY SCORES
ON CONFLICT (requirement_id, listing_id) DO UPDATE SET overall_score = EXCLUDED.overall_score;

-- 11. INQUIRIES, COMMERCIAL OFFERS & ORDERS
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (offer_number) DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT (order_number) DO NOTHING;

ON CONFLICT DO NOTHING;

-- 12. LOGISTICS QUOTES, SHIPMENTS, ROUTES & TELEMETRY EVENTS
ON CONFLICT DO NOTHING;

ON CONFLICT (shipment_number) DO NOTHING;

ON CONFLICT (shipment_id, sequence_number) DO NOTHING;

ON CONFLICT DO NOTHING;

-- 13. INVOICES & PAYMENTS
ON CONFLICT (invoice_number) DO NOTHING;

ON CONFLICT DO NOTHING;

-- 14. NOTIFICATIONS, AUDIT LOGS & SYSTEM ALERTS
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

COMMIT;

-- CarbonLoop Large Scale Database Seed Complete!